// Données pures du panneau Git : palette, analyse des sorties git et gh, étape suggérée,
// libellés. Aucun appel au moteur ici : tout ce qui touche `$` vit dans register.tsx.

import type { Action, CiWatch, Form, GitBranch, GitCommit, GitFile, GitRemoteBranch, GitRepo, Meta, PrChecks, PrState, PullRequest, Running } from '../types'

// Couleurs brutes (hex) mi-tons, copiées de flow-board (hooks/catalog.ts) : lisibles en thème
// clair comme sombre, sur le terminal comme sur le desktop.
export const C = {
  violet: '#9B7BEA',
  lilac: '#B79BF5',
  blue: '#4A9EE8',
  cyan: '#2EB8C9',
  teal: '#3FB68B',
  tangerine: '#E8913A',
  coral: '#EF7D57',
  amber: '#D9A520',
  green: '#4CB782',
  red: '#E5534B',
  pink: '#E06C9F',
  magenta: '#C36BD9',
  indigo: '#7C83F2',
  sky: '#56B4E9',
  sand: '#C9A66B',
  slate: '#7F8EA3',
  gray: '#8B8B93',
  /** Texte foncé posé sur un aplat de couleur. */
  ink: '#17171C',
} as const

// L'app desktop fond les espaces ordinaires : les écarts dans un texte sont insécables.
// NB contient une espace insécable U+00A0 littérale (invisible) : ne pas la remplacer.
export const NB = ' '
export const SEP = `${NB}${NB}·${NB}${NB}`

// Rôles figés de la palette : cyan pour la sync et le distant (pull, push).
export const ACTION_COLOR: Record<Action, string> = { commit: C.green, pull: C.cyan, push: C.cyan, pr: C.violet }
export const OPERATION: Record<string, string> = { rebase: 'Rebase', merge: 'Merge', 'cherry-pick': 'Cherry-pick', revert: 'Revert' }
export const MAX_FILES = 80
export const MAX_COMMITS = 25

export const REF_FORMAT = '%(refname)%00%(HEAD)%00%(upstream:short)%00%(upstream:track,nobracket)%00%(committerdate:unix)%00%(subject)%00%(worktreepath)'
export const LOG_FORMAT = '%H%x00%h%x00%an%x00%ct%x00%D%x00%s'
export const PR_FIELDS = 'number,title,url,state,isDraft,baseRefName,headRefOid,reviewDecision,statusCheckRollup'

export type Run = { exitCode: number; stdout: string; stderr: string }
export type LoadOptions = { fetch?: boolean; pr?: boolean; say?: boolean }

type StatusFile = Omit<GitFile, 'added' | 'removed'>

// `git status --porcelain=v2 --branch --show-stash -z` : en-têtes `# …`, puis une entrée
// par fichier (1 ordinaire, 2 renommé suivi de l'ancien chemin, u conflit, ? non suivi).
export function parseStatus(out: string) {
  const s = { oid: null as string | null, branch: null as string | null, upstream: null as string | null, ahead: 0, behind: 0, stash: 0, files: [] as StatusFile[] }
  const parts = out.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i] ?? ''
    if (!rec) continue
    if (rec.startsWith('# ')) {
      const [key, ...rest] = rec.slice(2).split(' ')
      const value = rest.join(' ')
      if (key === 'branch.oid') s.oid = value === '(initial)' ? null : value
      else if (key === 'branch.head') s.branch = value === '(detached)' ? null : value
      else if (key === 'branch.upstream') s.upstream = value
      else if (key === 'branch.ab') {
        const ab = value.match(/\+(\d+) -(\d+)/)
        if (ab) {
          s.ahead = Number(ab[1])
          s.behind = Number(ab[2])
        }
      } else if (key === 'stash') s.stash = Number(value) || 0
      continue
    }
    const f = rec.split(' ')
    const xy = f[1] ?? '..'
    const index = xy[0] ?? '.'
    const work = xy[1] ?? '.'
    if (rec[0] === '1') s.files.push({ path: f.slice(8).join(' '), from: null, index, work, kind: 'changed' })
    else if (rec[0] === '2') s.files.push({ path: f.slice(9).join(' '), from: parts[++i] ?? null, index, work, kind: 'changed' })
    else if (rec[0] === 'u') s.files.push({ path: f.slice(10).join(' '), from: null, index, work, kind: 'conflict' })
    else if (rec[0] === '?') s.files.push({ path: rec.slice(2), from: null, index: '?', work: '?', kind: 'untracked' })
  }
  return s
}

// `git diff HEAD --numstat -z` : « ajouts\tretraits\tchemin », ou pour un renommage
// « ajouts\tretraits\t » suivi de l'ancien puis du nouveau chemin ; `-` pour un binaire.
export function parseNumstat(out: string) {
  const map = new Map<string, [number | null, number | null]>()
  const parts = out.split('\0')
  for (let i = 0; i < parts.length; i++) {
    const rec = parts[i]
    if (!rec) continue
    const [a, d, p] = rec.split('\t')
    let path = p
    if (p === '') {
      i += 2
      path = parts[i]
    }
    if (!path) continue
    map.set(path, [a === '-' || a === undefined ? null : Number(a), d === '-' || d === undefined ? null : Number(d)])
  }
  return map
}

export function parseRefs(out: string) {
  const locals: GitBranch[] = []
  const all: GitRemoteBranch[] = []
  for (const row of out.split('\n')) {
    if (!row) continue
    const [ref = '', head = '', upstream = '', track = '', date = '0', subject = '', worktree = ''] = row.split('\0')
    if (ref.startsWith('refs/heads/')) {
      locals.push({
        name: ref.slice('refs/heads/'.length),
        isCurrent: head === '*',
        upstream: upstream || null,
        ahead: Number(track.match(/ahead (\d+)/)?.[1] ?? 0),
        behind: Number(track.match(/behind (\d+)/)?.[1] ?? 0),
        isGone: track === 'gone',
        worktree: head !== '*' && worktree ? worktree : null,
        date: Number(date) * 1000,
        subject,
      })
    } else if (ref.startsWith('refs/remotes/') && !ref.endsWith('/HEAD')) {
      const name = ref.slice('refs/remotes/'.length)
      all.push({ name, local: localOf(name), date: Number(date) * 1000, subject })
    }
  }
  // La branche courante d'abord, puis les plus récentes.
  locals.sort((a, b) => Number(b.isCurrent) - Number(a.isCurrent))
  const names = new Set(locals.map((b) => b.name))
  const followed = new Set(locals.map((b) => b.upstream))
  return {
    locals,
    remotes: all.filter((b) => !names.has(b.local) && !followed.has(b.name)),
    remoteNames: new Set(all.map((b) => b.name)),
  }
}

export function parseLog(out: string, notPushed: Set<string>, hasRemote: boolean): GitCommit[] {
  return out
    .split('\n')
    .filter(Boolean)
    .map((row) => {
      const [hash = '', short = '', author = '', date = '0', refs = '', subject = ''] = row.split('\0')
      return { hash, short, author, date: Number(date) * 1000, refs, subject, isPushed: hasRemote && !notPushed.has(hash) }
    })
}

// « remote.origin.url https://… » → origin ↦ https://…
export function parseRemoteUrls(out: string) {
  const map = new Map<string, string>()
  for (const row of out.split('\n')) {
    const hit = row.trim().match(/^remote\.(.+)\.url\s+(.+)$/)
    if (hit && hit[1] && hit[2]) map.set(hit[1], hit[2])
  }
  return map
}

// Branche par défaut, dans l'ordre de reference/git.md du plugin project : origin/HEAD,
// sinon origin/main ou origin/master, sinon main ou master en local.
export function defaultOf(originHead: Run, locals: GitBranch[], remoteNames: Set<string>) {
  if (originHead.exitCode === 0 && originHead.stdout.trim()) return originHead.stdout.trim().replace(/^origin\//, '')
  for (const name of ['main', 'master']) if (remoteNames.has(`origin/${name}`)) return name
  for (const name of ['main', 'master']) if (locals.some((b) => b.name === name)) return name
  return null
}

// Adresse web d'un distant GitHub (https, ssh ou scp), sans identifiants.
export function githubUrl(url: string) {
  const hit = url.trim().match(/^(?:(?:https?|ssh):\/\/)?(?:[^@/]+@)?github\.com[:/](.+?)(?:\.git)?\/?$/i)
  return hit && hit[1] && /^[\w.-]+\/[\w.-]+$/.test(hit[1]) ? `https://github.com/${hit[1]}` : null
}

// Les vérifications GitHub : CheckRun (status, conclusion) et StatusContext (state).
// Le nom du premier check en échec est gardé pour le suivi de la CI. Un check annulé dont un
// homonyme (même workflow, même nom) n'est pas annulé a été remplacé, par exemple par
// `concurrency: cancel-in-progress` : il ne compte pas.
export function checksOf(list: any[]): PrChecks {
  const out: PrChecks = { passed: 0, failed: 0, pending: 0, firstFailed: null }
  const keyOf = (c: any) => `${c.workflowName ?? ''}\u0000${c.name || c.context || ''}`
  const isCancelled = (c: any) => String(c.conclusion || c.state || '').toUpperCase() === 'CANCELLED'
  const live = new Set(list.filter((c) => !isCancelled(c)).map(keyOf))
  for (const c of list) {
    if (isCancelled(c) && live.has(keyOf(c))) continue
    const verdict = String(c.conclusion || c.state || '').toUpperCase()
    if (c.status && String(c.status).toUpperCase() !== 'COMPLETED') out.pending += 1
    else if (['SUCCESS', 'NEUTRAL', 'SKIPPED'].includes(verdict)) out.passed += 1
    else if (['', 'PENDING', 'EXPECTED'].includes(verdict)) out.pending += 1
    else {
      out.failed += 1
      if (!out.firstFailed) out.firstFailed = String(c.name || c.context || c.workflowName || '') || null
    }
  }
  return out
}

// ─── Suivi de la CI après un push ───────────────────────────────────────────

/** Relecture des checks pendant le suivi. */
export const CI_EVERY_MS = 25_000
/** Plafond du suivi : au-delà, il s'arrête sur « CI encore en cours ». */
export const CI_CAP_MS = 20 * 60_000
/** Toujours aucun check au bout de ce délai : le dépôt n'a pas de CI pour ce commit. */
export const CI_WAIT_MS = 3 * 60_000
export const RUN_FIELDS = 'status,conclusion,name,url'

/**
 * `gh run list --commit <sha> --json status,conclusion,name,url` : les exécutions GitHub
 * Actions du commit, au même format de comptes que les checks d'une PR (minuscules ici).
 * Lève une erreur sur un JSON illisible.
 */
export function runsOf(stdout: string): PrChecks {
  const list = JSON.parse(stdout)
  return checksOf(Array.isArray(list) ? list : [])
}

/** Où en est la CI, d'après les checks lus et le temps écoulé depuis le push. */
export function ciPhaseOf(c: PrChecks, elapsedMs: number): NonNullable<CiWatch>['phase'] {
  const total = c.passed + c.failed + c.pending
  if (total === 0) return elapsedMs >= CI_WAIT_MS ? 'none' : 'waiting'
  if (c.pending > 0) return elapsedMs >= CI_CAP_MS ? 'timeout' : 'running'
  return c.failed > 0 ? 'failed' : 'passed'
}

export function isCiActive(w: CiWatch) {
  return w !== null && (w.phase === 'waiting' || w.phase === 'running')
}

/** Le suivi de la CI à afficher : seulement celui de la branche et du commit en tête. */
export function ciOf(r: GitRepo, w: CiWatch): NonNullable<CiWatch> | null {
  if (!w || w.root !== r.root || w.branch !== r.branch || (r.oid !== null && r.oid !== w.sha)) return null
  return w
}

/**
 * L'état de la CI en un mot : en attente (rien encore lancé), en cours (finis/total),
 * réussie, échouée (premier check en échec), ou aucun check. `isShort` pour le bandeau.
 */
export function ciText(w: NonNullable<CiWatch>, isShort = false): [string, string] {
  const c = w.checks
  const total = c.passed + c.failed + c.pending
  if (w.phase === 'waiting') return [isShort ? `◌${NB}CI` : `◌${NB}CI${NB}en${NB}attente`, C.amber]
  if (w.phase === 'running') return [`◌${NB}CI${NB}${total - c.pending}/${total}`, C.amber]
  if (w.phase === 'timeout') return [isShort ? `◌${NB}CI${NB}?` : `◌${NB}CI${NB}encore${NB}en${NB}cours${NB}(suivi${NB}arrêté)`, C.amber]
  if (w.phase === 'none') return [`aucun${NB}check`, C.gray]
  if (w.phase === 'failed') {
    const name = c.firstFailed ? `${isShort ? NB : `${NB}:${NB}`}${c.firstFailed}` : ''
    return [`✗${NB}CI${isShort ? '' : `${NB}échouée`}${name}`, C.red]
  }
  return [isShort ? `✓${NB}CI` : `✓${NB}CI${NB}réussie`, C.green]
}

/**
 * La réponse JSON de `gh pr view` ; lève une erreur sur un JSON illisible ou incomplet
 * (relevée par `refresh`, après l'écriture du dépôt). Sans numéro ni adresse, la PR ne
 * peut pas se dessiner : un lien sans `href` ferait refuser tout le panneau.
 */
export function prOf(branch: string, stdout: string): PrState {
  const d = JSON.parse(stdout)
  if (typeof d?.number !== 'number' || typeof d?.url !== 'string' || !/^https:\/\//.test(d.url)) {
    throw new Error('gh : réponse incomplète (numéro ou adresse de la PR absents).')
  }
  return {
    branch,
    pr: {
      number: d.number,
      title: d.title ?? '',
      url: d.url,
      state: d.state,
      isDraft: Boolean(d.isDraft),
      base: d.baseRefName ?? '',
      head: typeof d.headRefOid === 'string' && d.headRefOid ? d.headRefOid : null,
      review: d.reviewDecision || null,
      checks: checksOf(d.statusCheckRollup ?? []),
    },
    error: null,
  }
}

export function commandFor(a: Action, r: GitRepo, f: Form) {
  if (a === 'commit') return { name: 'commit', args: f.hint.trim() }
  if (a === 'pull') return { name: 'sync', args: f.pullFrom === 'base' && r.defaultBranch && r.branch && r.branch !== r.defaultBranch ? 'base' : '' }
  if (a === 'push') return { name: 'push', args: '' }
  // La base choisie, si elle existe encore ; la branche par défaut se passe d'argument.
  const base = f.prBase && f.prBase !== r.defaultBranch && f.prBase !== r.branch && r.branches.some((b) => b.name === f.prBase) ? f.prBase : ''
  return { name: 'pr', args: [base, f.prDraft ? '--draft' : '', f.prAuto ? '--auto' : ''].filter(Boolean).join(' ') }
}

/** Suggérée avant le push : le numéro de version et le CHANGELOG partent avec les commits. */
export const VERSION_COMMAND = '/project:version'

export function slash(c: { name: string; args: string }) {
  return `/project:${c.name}${c.args ? ` ${c.args}` : ''}`
}

/** L'étape logique suivante ; rien pendant une opération ou un conflit. */
export function suggest(r: GitRepo, p: PrState): Action | null {
  if (r.operation || r.files.some((x) => x.kind === 'conflict')) return null
  if (r.files.length) return 'commit'
  if (r.behind) return 'pull'
  if (r.hasRemote && (r.ahead || (!r.upstream && r.branch && r.branch !== r.defaultBranch))) return 'push'
  if (r.webUrl && r.branch && r.branch !== r.defaultBranch && r.upstream && p && p.branch === r.branch && !p.error && !prOfBranch(r, p)) return 'pr'
  return null
}

/** La ligne d'état (relais du bandeau masqué). */
export function statusText(r: GitRepo) {
  const parts = [`⎇ ${branchLabel(r)}`]
  if (r.ahead) parts.push(`↑${r.ahead}`)
  if (r.behind) parts.push(`↓${r.behind}`)
  const text = parts.join(' ')
  return r.files.length ? `${text} · ${r.files.length} modif.` : text
}

export function branchLabel(r: GitRepo) {
  return r.branch ?? `HEAD détachée (${r.head ?? '?'})`
}

/** Comptes des fichiers : conflits, suivis modifiés, non suivis, et le total des lignes. */
export function countsOf(r: GitRepo) {
  const conflicts = r.files.filter((x) => x.kind === 'conflict').length
  const fresh = r.files.filter((x) => x.kind === 'untracked').length
  const added = r.files.reduce((n, x) => n + (x.added ?? 0), 0)
  const removed = r.files.reduce((n, x) => n + (x.removed ?? 0), 0)
  return { conflicts, fresh, changed: r.files.length - conflicts - fresh, added, removed }
}

/**
 * La PR de la branche courante seulement. `gh pr view <branche>` rend la dernière PR de la
 * branche, même fusionnée ou fermée : une branche réutilisée après une fusion (dev, par
 * exemple) garderait l'ancienne PR et sa route toute faite. Une PR fusionnée ou fermée ne
 * compte que tant que HEAD est encore sa tête ; au-delà, les nouveaux commits n'en ont pas.
 */
export function prOfBranch(r: GitRepo, p: PrState): PullRequest | null {
  if (!p || p.branch !== (r.branch ?? '') || !p.pr) return null
  const pr = p.pr
  if (pr.state !== 'OPEN' && pr.head && r.head && pr.head.slice(0, r.head.length) !== r.head) return null
  return pr
}

export function glyphOf(f: GitFile) {
  // Mêmes glyphes et couleurs que les groupes, les pastilles et le bandeau.
  if (f.kind === 'conflict') return { letter: '✖', color: C.red }
  if (f.kind === 'untracked') return { letter: '+', color: C.teal }
  const x = f.work !== '.' ? f.work : f.index
  return { letter: x, color: x === 'A' ? C.green : x === 'D' ? C.red : x === 'R' || x === 'C' ? C.blue : C.amber }
}

export function prLabel(p: PullRequest) {
  if (p.state === 'MERGED') return 'Fusionnée'
  if (p.state === 'CLOSED') return 'Fermée'
  return p.isDraft ? 'Brouillon' : 'Ouverte'
}

export function prColor(p: PullRequest) {
  if (p.state === 'MERGED') return C.violet
  if (p.state === 'CLOSED') return C.red
  return p.isDraft ? C.gray : C.green
}

export function reviewOf(review: string | null): [string, string] | null {
  if (review === 'APPROVED') return ['approuvée', C.green]
  if (review === 'CHANGES_REQUESTED') return ['modifications demandées', C.red]
  if (review === 'REVIEW_REQUIRED') return ['relecture attendue', C.gray]
  return null
}

export function checksText(c: PrChecks): [string, string][] {
  return [
    c.passed ? ([`✓${NB}${c.passed}`, C.green] as [string, string]) : null,
    c.failed ? ([`✗${NB}${c.failed}`, C.red] as [string, string]) : null,
    c.pending ? ([`◌${NB}${c.pending}`, C.amber] as [string, string]) : null,
  ].filter((x): x is [string, string] => x !== null)
}

/**
 * « fetch il y a 4 min », « fetch en échec », ou « fetch jamais » quand ni la session ni
 * `FETCH_HEAD` ne donnent d'âge : « ✓ à jour » ne vaut que ce que vaut le dernier fetch.
 * Rien sans distant (il n'y a rien à récupérer).
 */
export function fetchedText(m: Meta, now: number, hasRemote: boolean): { text: string; isError: boolean } | null {
  if (m.fetchError) return { text: `fetch${NB}en${NB}échec`, isError: true }
  if (m.fetchedAt) return { text: `fetch${NB}${ago(m.fetchedAt, now)}`, isError: false }
  return hasRemote ? { text: `fetch${NB}jamais`, isError: false } : null
}

export function gitError(res: Run) {
  const lines = res.stderr
    .split('\n')
    .map((x) => x.trim())
    .filter(Boolean)
  return lines.slice(0, 4).join(' ') || `git a échoué (code ${res.exitCode})`
}

export function firstLine(text: string) {
  return text.split('\n').map((x) => x.trim()).find(Boolean) ?? ''
}

// origin/feat/x → feat/x
export function localOf(remote: string) {
  return remote.replace(/^[^/]+\//, '')
}

/** Comparaison de dossiers insensible à la casse et aux `\` / `/` (Windows). */
export function sameDir(a: string, b: string) {
  const norm = (p: string) => p.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
  return norm(a) === norm(b)
}

export function unique(list: string[]) {
  return [...new Set(list)]
}

export function plural(n: number, one: string, many = `${one}s`) {
  return `${n}${NB}${n > 1 ? many : one}`
}

/** Âge relatif : « à l'instant », « il y a 4 min », « hier », puis la date. */
export function ago(ms: number, now: number) {
  const s = Math.max(0, Math.round((now - ms) / 1000))
  if (s < 60) return `à${NB}l'instant`
  const min = Math.round(s / 60)
  if (min < 60) return `il${NB}y${NB}a${NB}${min}${NB}min`
  const h = Math.round(min / 60)
  if (h < 24) return `il${NB}y${NB}a${NB}${h}${NB}h`
  const d = Math.round(h / 24)
  if (d === 1) return 'hier'
  if (d < 30) return `il${NB}y${NB}a${NB}${d}${NB}j`
  const date = new Date(ms)
  return `${pad(date.getDate())}/${pad(date.getMonth() + 1)}/${date.getFullYear()}`
}

function pad(n: number) {
  return String(n).padStart(2, '0')
}

/** Arguments réservés de /git : les onglets (identifiants ou libellés) et hide / show. */
export function tabOfArg(arg: string): 'changes' | 'branches' | 'history' | null {
  const a = arg.toLowerCase()
  if (a === 'changes' || a === 'modifications') return 'changes'
  if (a === 'branches') return 'branches'
  if (a === 'history' || a === 'historique') return 'history'
  return null
}

/**
 * Une commande /project lancée du panneau a-t-elle fait son effet ? Le dépôt relu le dit sans
 * attendre la fin du tour de Claude, qui peut enchaîner sur tout autre chose dans le même tour.
 * Commit : HEAD a bougé. Sync : un fetch depuis le lancement et plus rien à récupérer. Push :
 * plus rien à pousser vers le suivi. PR : une PR existe pour HEAD (voir `prOfBranch`). Une commande sans ces
 * repères (lancée par une version précédente) n'est finie qu'avec le tour.
 */
export function isRunDone(run: NonNullable<Running>, r: GitRepo, m: Meta, p: PrState): boolean {
  if (!run.isStarted || run.startedAt === undefined) return false
  if (run.action === 'commit') return run.head !== undefined && r.head !== null && r.head !== run.head
  if (run.action === 'pull') return (m.fetchedAt ?? 0) >= run.startedAt && r.behind === 0 && !r.operation
  if (run.action === 'push') return Boolean(r.upstream) && r.ahead === 0
  if (run.action === 'pr') return prOfBranch(r, p) !== null
  return false
}

files.hooks/view.tsx:
// Dessin du panneau Git (/git) et du bandeau au-dessus du prompt. Un seul arbre pour
// toutes les surfaces : le desktop, VS Code et le mobile reçoivent les SVG, le terminal
// des glyphes et des barres en blocs. Aucun appel au moteur ici : l'état arrive dans
// `View`, les actions dans `Actions` (des fermetures préparées par register.tsx).
//
// Pièges du desktop : les espaces ordinaires y sont fondus et `gap` ignoré ; les écarts
// dans un texte sont donc insécables, ceux entre éléments des marges. Aucune prop n'est
// passée à `undefined` : les arbres restent valides partout. Le mobile n'a ni `Input` ni
// `Select` : le panneau s'en passe et le dit en une ligne atténuée.

import type { Action, CiWatch, Expanded, Form, GitBranch, GitCommit, GitFile, GitRemoteBranch, GitRepo, Meta, Notice, PrState, PullRequest, Running, Switching, Tab } from '../types'
import {
  ACTION_COLOR,
  C,
  MAX_FILES,
  NB,
  OPERATION,
  SEP,
  ago,
  branchLabel,
  checksText,
  ciOf,
  ciText,
  commandFor,
  countsOf,
  fetchedText,
  glyphOf,
  localOf,
  plural,
  prColor,
  prLabel,
  prOfBranch,
  reviewOf,
  sameDir,
  slash,
  VERSION_COMMAND,
  suggest,
  unique,
} from './model.ts'
import { barSvg, gaugeSvg, roadmapSvg, spinnerSvg, type BarPart, type NodeState, type RoadNode } from './svg.ts'

/** Largeur estimée d'une cellule sur les surfaces distantes ; un SVG trop large est réduit à sa place. */
const PX_PER_CELL = 7.6
/** Plafonds des listes avant « ▸ tout voir (N) ». */
const FILES_CAP = 20
const BRANCHES_CAP = 12
const COMMITS_CAP = 12

export type Kit = {
  Box: any
  Text: any
  Button: any
  Svg: any
  /** Lien externe ; absent d'une table qui n'en a pas. */
  Link: any
  /** Champ de saisie et liste de choix : absents sur le mobile. */
  Input: any
  Select: any
  /** La surface dessine les SVG (desktop, VS Code, mobile). */
  isRich: boolean
  /** Colonnes du corps. */
  width: number
}

/**
 * Ce que la surface dessine vraiment. La table de `$.ui.resolve(e)` est complétée : un
 * élément absent de la surface y figure quand même et dessine un fragment vide (constaté
 * dans le kit de test : `Svg` sur le terminal, `Input` et `Select` sur le mobile). Un
 * `typeof table.Svg` ne suffit donc pas : register.tsx lit ces capacités dans le contrat
 * `Elements` du moteur et les passe ici, la vue ne connaît pas le nom de la surface.
 */
export type Caps = { hasSvg: boolean; hasFields: boolean }

export const kitOf = (table: Record<string, unknown>, width: number, caps: Caps): Kit => ({
  Box: table.Box,
  Text: table.Text,
  Button: table.Button,
  Svg: caps.hasSvg ? (table.Svg ?? null) : null,
  Link: table.Link ?? null,
  Input: caps.hasFields ? (table.Input ?? null) : null,
  Select: caps.hasFields ? (table.Select ?? null) : null,
  isRich: caps.hasSvg && typeof table.Svg === 'function',
  width: Math.max(24, Math.floor(width)),
})

export type View = {
  repo: GitRepo | null
  pr: PrState
  meta: Meta
  tab: Tab
  action: Action | null
  form: Form
  notice: Notice
  busy: string | null
  running: Running
  switching: Switching
  showRemotes: boolean
  expanded: Expanded
  isBandHidden: boolean
  /** Suivi de la CI après un push ; affiché seulement pour la branche et le commit en tête. */
  ci: CiWatch
  now: number
}

export type Actions = {
  setTab: (tab: Tab) => unknown
  /** Ouvre le tiroir d'une action, ou le referme. */
  toggleAction: (a: Action) => unknown
  closeAction: () => unknown
  setForm: (patch: Partial<Form>) => unknown
  /** ↻ : oublie une commande restée en file, puis relit tout (fetch et PR compris). */
  refresh: () => unknown
  launch: (a: Action) => unknown
  /** Lance /project:version, suggérée avant le push. */
  launchVersion: () => unknown
  openFolder: (value: string) => unknown
  /** Revient au dossier de la session. */
  backToSession: () => unknown
  askSwitch: (name: string, isRemote: boolean) => unknown
  confirmSwitch: (name: string, isRemote: boolean) => unknown
  cancelSwitch: () => unknown
  createBranch: (value: string) => unknown
  toggleRemotes: () => unknown
  toggleExpanded: (list: keyof Expanded) => unknown
  dismissNotice: () => unknown
  hideBand: () => unknown
  openPane: () => unknown
}

// ─── Petits outils ────────────────────────────────────────────────────────

const SPIN = '⠋⠙⠹⠸⠼⠴⠦⠧⠇⠏'
const spinFrame = (now: number): string => SPIN[Math.floor(now / 1000) % SPIN.length] ?? '⠋'
const px = (cells: number): number => Math.max(160, Math.floor(cells * PX_PER_CELL))

type Style = { color?: string; bg?: string; bold?: boolean; dim?: boolean; italic?: boolean; strike?: boolean; wrap?: string }

const propsOf = (style: Style): Record<string, unknown> => {
  const props: Record<string, unknown> = {}
  if (style.color) props.color = style.color
  if (style.bg) props.backgroundColor = style.bg
  if (style.bold) props.bold = true
  if (style.dim) props.dimColor = true
  if (style.italic) props.italic = true
  if (style.strike) props.strikethrough = true
  if (style.wrap) props.wrap = style.wrap
  return props
}

/** Un Text sans prop indéfinie. */
const T = (k: Kit, text: string, style: Style = {}): unknown => h(k.Text, propsOf(style), text)

/** Un Text fait de morceaux (Text imbriqués ou chaînes), sans prop indéfinie. */
const TT = (k: Kit, parts: unknown[], style: Style = {}): unknown => h(k.Text, propsOf(style), ...parts.filter(isShown))

/** Pastille pleine : texte foncé sur la couleur. `style` ajoute par exemple une troncature. */
const chip = (k: Kit, text: string, color: string, style: Style = {}): unknown => T(k, `${NB}${text}${NB}`, { ...style, bg: color, color: C.ink, bold: true })

const isShown = (item: unknown): boolean => item !== null && item !== undefined && item !== false && item !== ''

/** Une rangée d'éléments séparés par une marge (le desktop ignore `gap`). */
const line = (k: Kit, items: unknown[], wrap = false): unknown => {
  const { Box } = k
  const list = items.filter(isShown)
  return (
    <Box flexDirection="row" alignItems="center" flexWrap={wrap ? 'wrap' : 'nowrap'}>
      {list.map((item, i) => (i < list.length - 1 ? <Box marginRight={1}>{item}</Box> : item))}
    </Box>
  )
}

const svgOf = (k: Kit, drawn: { source: string; width: number; height: number }, alt: string, isSized = true): unknown => {
  const props: Record<string, unknown> = { source: drawn.source, alt }
  if (isSized) {
    props.width = drawn.width
    props.height = drawn.height
  }
  // Jamais `isInteractive` : ce mode dessine dans un cadre à fond blanc, rechargé (donc
  // clignotant) à chaque redessin. En image, le fond reste transparent et le dessin stable.
  return h(k.Svg, props)
}

/** Barre en blocs du terminal. */
const blocks = (k: Kit, parts: readonly BarPart[], total: number, cells: number): unknown => {
  const { Box } = k
  const width = Math.max(6, cells)
  const sum = Math.max(1, total, parts.reduce((n, p) => n + p.value, 0))
  let used = 0
  const segs: unknown[] = []
  parts.forEach((part) => {
    if (part.value <= 0) return
    const n = Math.max(1, Math.round((part.value / sum) * width))
    const take = Math.min(n, width - used)
    if (take <= 0) return
    used += take
    segs.push(T(k, '█'.repeat(take), { color: part.color }))
  })
  if (used < width) segs.push(T(k, '░'.repeat(width - used), { color: C.gray, dim: true }))
  return <Box flexDirection="row">{segs}</Box>
}

/** Indicateur de travail : arc qui tourne (SVG) ou spinner braille (terminal). */
const spinner = (k: Kit, color: string, now: number, alt: string): unknown =>
  k.isRich ? svgOf(k, spinnerSvg(color, 12), alt) : T(k, spinFrame(now), { color })

/** Ce que la surface ne permet pas, dit en une ligne atténuée plutôt que caché en silence. */
const unavailable = (k: Kit, text: string, marginTop = 1): unknown => {
  const { Box } = k
  return <Box marginTop={marginTop}>{T(k, `⊘${NB}${text}`, { dim: true, wrap: 'wrap' })}</Box>
}

/** Bascule « ▸ tout voir (N) » / « ▾ réduire » d'une liste plafonnée. */
const showAllToggle = (k: Kit, key: string, isOpen: boolean, total: number, onPress: () => unknown): unknown => {
  const { Box, Button } = k
  return (
    <Box marginTop={1}>
      <Button key={key} plain={true} dimColor={true} label={isOpen ? `▾${NB}réduire` : `▸${NB}tout${NB}voir${NB}(${total})`} onPress={onPress} />
    </Box>
  )
}

const TONE = { ok: C.green, error: C.red, info: C.tangerine } as const

/** Couleur d'identité du mod (règle 8 : le violet est la marque du mod ; la mandarine dit « en cours »). */
const BRAND = C.violet

// ─── Route de livraison (Commit → Push → PR → Checks → Fusion) ────────────

/** Formes courtes de la route en texte, quand le libellé entier ne tient pas. */
const SHORT_LABEL: Record<string, string> = { Commit: 'Com.', Checks: 'CI', Fusion: 'Fus.' }

const STATE_WORD: Record<NodeState, string> = { done: 'fait', active: 'en cours', next: 'à lancer', pending: 'à venir', skipped: 'sauté' }

const roadNodes = (r: GitRepo, pr: PullRequest | null, watch: NonNullable<CiWatch> | null = null): RoadNode[] => {
  if (!r.hasRemote || !r.branch) return []
  const n = countsOf(r)
  const steps: { label: string; sub: string; color: string; isDone: boolean }[] = [
    { label: 'Commit', sub: r.files.length ? plural(r.files.length, 'fichier') : 'propre', color: n.conflicts ? C.red : C.green, isDone: r.files.length === 0 },
    {
      label: 'Push',
      sub: !r.upstream ? 'non publiée' : r.ahead ? `↑${r.ahead}` : 'à jour',
      color: C.cyan,
      isDone: Boolean(r.upstream) && r.ahead === 0,
    },
  ]
  if (r.webUrl && r.branch !== r.defaultBranch) {
    const live = pr && pr.state !== 'CLOSED' ? pr : null
    steps.push({ label: 'PR', sub: live ? `#${live.number}` : 'à ouvrir', color: C.violet, isDone: live !== null })
    // Pendant le suivi de la CI, ses checks l'emportent : « en attente » tant que rien n'est
    // lancé, au lieu d'un « aucun » fait (sans suivi, les deux se confondent).
    const ch = live ? (watch?.checks ?? live.checks) : undefined
    const hasChecks = ch !== undefined && ch.passed + ch.failed + ch.pending > 0
    const isWaiting = Boolean(live) && watch?.phase === 'waiting'
    steps.push({
      label: 'Checks',
      sub: !ch ? '' : isWaiting ? 'attente' : ch.failed ? `✗${ch.failed}` : ch.pending ? `◌${ch.pending}` : hasChecks ? `✓${ch.passed}` : 'aucun',
      color: ch && ch.failed ? C.red : C.cyan,
      isDone: Boolean(live) && ch !== undefined && !isWaiting && ch.failed === 0 && ch.pending === 0,
    })
    steps.push({ label: 'Fusion', sub: live?.state === 'MERGED' ? 'fusionnée' : '', color: C.violet, isDone: live?.state === 'MERGED' })
  }
  // Une route se parcourt dans l'ordre : la première étape non faite est active, et toutes
  // les suivantes sont à venir, même si leur état propre dit « fait ». Un commit à pousser
  // rend la PR, les checks et la fusion d'avant caducs : il en faudra de nouveaux. Leur
  // sous-titre ne garde que le numéro d'une PR encore ouverte, que le push mettra à jour.
  let isOpen = true
  return steps.map((s) => {
    let state: NodeState = 'pending'
    let sub = s.sub
    if (s.isDone && isOpen) state = 'done'
    else if (isOpen) {
      state = 'active'
      isOpen = false
    } else if (!(s.label === 'PR' && pr?.state === 'OPEN')) sub = ''
    return sub ? { label: s.label, sub, color: s.color, state } : { label: s.label, color: s.color, state }
  })
}

/** La route en texte (repli terminal) : glyphes reliés, libellés dessous. */
const textRoad = (k: Kit, nodes: readonly RoadNode[], cells: number): unknown => {
  const { Box } = k
  const n = nodes.length
  const slot = Math.max(3, Math.floor((cells - 1) / Math.max(1, n)))
  const glyph = (x: RoadNode): string => (x.state === 'done' ? '●' : x.state === 'active' ? '◉' : x.state === 'next' ? '◎' : x.state === 'skipped' ? '·' : '○')
  const marks: unknown[] = []
  const labels: unknown[] = []
  nodes.forEach((x, i) => {
    const isLit = x.state !== 'pending' && x.state !== 'skipped'
    marks.push(T(k, glyph(x), { color: isLit ? x.color : C.gray, bold: x.state === 'active' }))
    if (i < n - 1) {
      const isDone = x.state === 'done' || x.state === 'skipped'
      marks.push(T(k, (isDone ? '━' : x.state === 'active' ? '╍' : '┄').repeat(slot - 1), { color: isDone ? x.color : C.gray, dim: !isDone }))
    }
    // Un libellé entier ou sa forme courte fixe, jamais coupé au milieu du mot.
    const showLabel = slot >= 6 || x.state === 'active'
    const short = SHORT_LABEL[x.label] ?? x.label
    const text = !showLabel ? '' : x.label.length <= slot - 1 ? x.label : short.length <= slot - 1 ? short : ''
    labels.push(T(k, i < n - 1 ? text.padEnd(slot) : text, { color: x.state === 'active' ? x.color : '', bold: x.state === 'active', dim: x.state !== 'active' }))
  })
  return (
    <Box flexDirection="column" marginTop={1}>
      <Box flexDirection="row">{marks}</Box>
      <Box flexDirection="row">{labels}</Box>
    </Box>
  )
}

const roadmap = (k: Kit, r: GitRepo, pr: PullRequest | null, watch: NonNullable<CiWatch> | null, cells: number): unknown => {
  const { Box } = k
  const nodes = roadNodes(r, pr, watch)
  if (nodes.length === 0) return null
  if (!k.isRich) return textRoad(k, nodes, cells)
  const alt = nodes.map((x) => `${x.label} : ${STATE_WORD[x.state]}${x.sub ? ` (${x.sub})` : ''}`).join(', ')
  return <Box marginTop={1}>{svgOf(k, roadmapSvg(nodes, px(cells)), alt, false)}</Box>
}

// ─── Panneau ──────────────────────────────────────────────────────────────

export const drawPane = (k: Kit, view: View, act: Actions): unknown => {
  const { Box } = k
  const r = view.repo
  if (!r) {
    return (
      <Box flexDirection="column" paddingX={1} paddingBottom={1}>
        {welcome(k, view, act)}
        {activity(k, view, act)}
      </Box>
    )
  }
  const body = view.tab === 'branches' ? branchesTab(k, view, r, act) : view.tab === 'history' ? historyTab(k, view, r, act) : changesTab(k, view, r, act)
  return (
    <Box flexDirection="column" paddingX={1} paddingBottom={1}>
      {hero(k, view, r, act)}
      {activity(k, view, act)}
      {operationCard(k, r)}
      {actionBar(k, view, r, act)}
      {drawer(k, view, r, act)}
      {tabsRow(k, view, r, act)}
      {body}
    </Box>
  )
}

/** Sans dépôt : une carte d'accueil, jamais un panneau vide. */
const welcome = (k: Kit, view: View, act: Actions): unknown => {
  const { Box, Button, Input } = k
  const m = view.meta
  return (
    <Box key="empty" flexDirection="column" borderStyle="round" borderColor={C.violet} paddingX={2} paddingY={1}>
      {/* Pendant une lecture, l'indicateur est dans la zone d'activité, juste dessous. */}
      {T(k, m.loading ? `◆${NB}Git` : `◆${NB}Pas de dépôt git ici`, { color: C.violet, bold: true })}
      {m.error && T(k, m.error, { dim: true, wrap: 'wrap' })}
      {T(k, 'Le panneau se remplit dès que le dossier suivi est dans un dépôt git.', { dim: true, wrap: 'wrap' })}
      {Input ? (
        <Box flexDirection="column" marginTop={1}>
          <Input key="folder" label="Dossier" placeholder="chemin d'un dépôt git" submitLabel="ouvrir" onSubmit={(v: string) => act.openFolder(v)} />
          <Box marginTop={1}>{T(k, 'ou /git <dossier>', { dim: true })}</Box>
        </Box>
      ) : (
        unavailable(k, 'Saisie du dossier indisponible ici : tape /git <dossier>.')
      )}
      {m.folder !== null && (
        <Box marginTop={1}>
          <Button key="back-session" label={`↩${NB}Dossier${NB}de${NB}la${NB}session`} onPress={() => act.backToSession()} />
        </Box>
      )}
    </Box>
  )
}

/**
 * Carte d'en-tête : pastille de la branche, jauge ↑/↓ (SVG) à gauche du dépôt et de sa
 * méta, état en pastilles par gravité, PR sur une ligne, route. Chaque chiffre n'y est
 * dit qu'une fois : sur une surface riche la jauge porte ↑/↓, ailleurs ce sont les pastilles.
 */
const hero = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box, Button, Link } = k
  const m = view.meta
  const n = countsOf(r)
  const pr = prOfBranch(r, view.pr)
  const prs = view.pr
  const watch = ciOf(r, view.ci)
  const inner = k.width - 6
  const color = r.operation || n.conflicts ? C.red : r.branch ? BRAND : C.gray
  const isHere = m.sessionRoot !== null && sameDir(m.sessionRoot, r.root)
  const fetched = fetchedText(m, view.now, r.hasRemote)
  const hasGauge = k.isRich && Boolean(r.upstream)

  // L'état, par gravité : ce qui bloque d'abord, l'anecdotique (stash) en dernier.
  const pills: [string, string][] = []
  if (r.operation) pills.push([`${OPERATION[r.operation] ?? r.operation}${NB}en${NB}cours`, C.red])
  if (n.conflicts) pills.push([`✖${NB}${n.conflicts}${NB}en${NB}conflit`, C.red])
  if (r.branch && r.upstream) {
    if (r.behind && !hasGauge) pills.push([`↓${NB}${r.behind}${NB}à${NB}récupérer`, C.amber])
    if (r.ahead && !hasGauge) pills.push([`↑${NB}${r.ahead}${NB}à${NB}pousser`, C.green])
    if (!r.ahead && !r.behind) pills.push([`✓${NB}à${NB}jour`, C.green])
  } else if (r.branch && r.hasRemote) {
    pills.push([`◌${NB}non${NB}publiée`, C.amber])
  }
  if (n.changed) pills.push([`●${NB}${n.changed}${NB}modifié${n.changed > 1 ? 's' : ''}`, C.amber])
  if (n.fresh) pills.push([`+${NB}${n.fresh}${NB}nouveau${n.fresh > 1 ? 'x' : ''}`, C.teal])
  if (r.stash) pills.push([`⚑${NB}${r.stash}${NB}stash`, C.slate])

  const gauge = hasGauge
    ? svgOf(k, gaugeSvg(r.ahead, r.behind, C.green, C.amber), `${r.ahead} commit${r.ahead > 1 ? 's' : ''} à pousser, ${r.behind} à récupérer`)
    : null
  const meta = [r.upstream ? `suit${NB}${r.upstream}` : r.hasRemote ? 'aucune branche distante suivie' : 'pas de distant', fetched && !fetched.isError ? fetched.text : null]
    .filter(Boolean)
    .join(SEP)

  // La pastille vivante ne dit que la commande /project ; lectures et bascules sont dans
  // la zone d'activité, juste dessous.
  const pending = view.running
  const live = pending !== null ? T(k, pending.isStarted ? `◉${NB}Claude${NB}travaille` : `▶${NB}en${NB}file`, { color: C.tangerine, bold: true }) : null

  const review = pr ? reviewOf(pr.review) : null
  const prLine = pr ? (
    <Box key="pr" flexDirection="row" justifyContent="space-between" alignItems="center" marginTop={1}>
      <Box flexShrink={1}>
        {TT(
          k,
          [
            T(k, `⇄${NB}#${pr.number}`, { color: C.violet, bold: true }),
            T(k, SEP, { dim: true }),
            T(k, prLabel(pr), { color: prColor(pr), bold: true }),
            ...(review ? [T(k, SEP, { dim: true }), T(k, review[0], { color: review[1] })] : []),
            ...(watch ? [ciText(watch)] : checksText(pr.checks)).flatMap(([text, c]) => [T(k, SEP, { dim: true }), T(k, text, { color: c })]),
            pr.title ? T(k, `${SEP}${pr.title}`, { dim: true }) : '',
          ],
          { wrap: 'truncate-end' },
        )}
      </Box>
      {Link && pr.url && (
        <Box flexShrink={0} marginLeft={1}>
          <Link href={pr.url} label="Ouvrir ↗" />
        </Box>
      )}
    </Box>
  ) : prs && prs.branch === (r.branch ?? '') && !prs.error && r.webUrl && r.branch && r.branch !== r.defaultBranch ? (
    <Box key="no-pr" marginTop={1}>
      {T(k, `⇄${NB}pas encore de pull request pour cette branche`, { dim: true, wrap: 'truncate-end' })}
    </Box>
  ) : null

  return (
    <Box key="head" flexDirection="column" borderStyle="round" borderColor={color} paddingX={1}>
      <Box flexDirection="row" justifyContent="space-between" alignItems="center">
        <Box flexShrink={1}>{chip(k, `⎇${NB}${branchLabel(r)}`, color, { wrap: 'truncate-end' })}</Box>
        <Box flexDirection="row" flexShrink={0} marginLeft={1} alignItems="center">
          {live && <Box marginRight={1}>{live}</Box>}
          {m.folder !== null && (
            <Box marginRight={1}>
              <Button key="back-session" plain={true} dimColor={true} label={`↩${NB}session`} onPress={() => act.backToSession()} />
            </Box>
          )}
          <Button key="refresh" plain={true} label={`↻${NB}Relire`} onPress={() => act.refresh()} />
        </Box>
      </Box>
      <Box flexDirection="row" alignItems="center" marginTop={1}>
        {gauge && (
          <Box marginRight={2} flexShrink={0}>
            {gauge}
          </Box>
        )}
        <Box flexDirection="column" flexShrink={1}>
          {TT(k, [T(k, r.name, { bold: true }), T(k, `${SEP}${meta}`, { dim: true })], { wrap: 'truncate-end' })}
          {fetched && fetched.isError && T(k, `${fetched.text}${m.fetchError ? ` : ${m.fetchError}` : ''}`, { color: C.red, wrap: 'truncate-end' })}
          {!isHere && T(k, `↗${NB}hors du dossier de la session : les commandes /project n'agissent pas ici`, { color: C.amber, wrap: 'truncate-end' })}
        </Box>
      </Box>
      {pills.length > 0 && <Box marginTop={1}>{line(k, pills.map(([text, c]) => chip(k, text, c)), true)}</Box>}
      {prLine}
      {/* Sans PR, la CI suivie après un push a sa propre ligne. */}
      {!pr && watch && <Box marginTop={1}>{T(k, ciText(watch)[0], { color: ciText(watch)[1], wrap: 'truncate-end' })}</Box>}
      {prs && prs.branch === (r.branch ?? '') && prs.error && <Box marginTop={1}>{T(k, prs.error, { color: C.amber, wrap: 'truncate-end' })}</Box>}
      {roadmap(k, r, pr, watch, inner)}
    </Box>
  )
}

/** La zone d'activité, toujours juste sous la carte d'en-tête. */
const activity = (k: Kit, view: View, act: Actions): unknown => {
  const { Box, Button } = k
  const m = view.meta
  const run = view.running
  const said = view.notice
  const rows = [
    m.loading && line(k, [spinner(k, C.gray, view.now, 'lecture'), T(k, m.loading, { color: C.gray })]),
    view.busy && line(k, [spinner(k, C.tangerine, view.now, 'git au travail'), T(k, view.busy, { color: C.tangerine })]),
    run &&
      (run.isStarted
        ? T(k, `◉${NB}${run.command} en cours dans la conversation…`, { color: C.tangerine, wrap: 'wrap' })
        : T(k, `▶${NB}${run.command} en file : il part dès que Claude est libre.`, { color: C.tangerine, wrap: 'wrap' })),
    said && (
      <Box flexDirection="row" justifyContent="space-between">
        <Box flexShrink={1}>{T(k, said.text, { color: TONE[said.tone], wrap: 'wrap' })}</Box>
        {said.tone === 'error' && (
          <Box flexShrink={0} marginLeft={1}>
            <Button key="notice-dismiss" plain={true} dimColor={true} label="x" onPress={() => act.dismissNotice()} />
          </Box>
        )}
      </Box>
    ),
  ].filter(isShown)
  if (rows.length === 0) return null
  return (
    <Box key="activity" flexDirection="column" marginTop={1} paddingX={1}>
      {rows}
    </Box>
  )
}

const operationCard = (k: Kit, r: GitRepo): unknown => {
  const { Box } = k
  if (!r.operation) return null
  const n = countsOf(r).conflicts
  return (
    <Box key="operation" flexDirection="column" borderStyle="round" borderColor={C.red} paddingX={1} marginTop={1}>
      {T(k, `${OPERATION[r.operation] ?? r.operation} en cours`, { color: C.red, bold: true })}
      {T(k, n ? `${plural(n, 'fichier')} en conflit : résous-les, puis termine ou annule l'opération.` : "Termine-la ou annule-la avant de commiter ou de changer de branche.", { dim: true, wrap: 'wrap' })}
    </Box>
  )
}

/**
 * Barre d'actions : un seul `primary`, l'étape suggérée, et seulement tant que son tiroir
 * est fermé (le tiroir porte alors « ▶ Lancer »). Le tiroir ouvert est marqué « ▾ ». Pas
 * de comptes dans les libellés : l'en-tête les dit déjà.
 */
const actionBar = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box, Button } = k
  const lead = suggest(r, view.pr)
  const pr = prOfBranch(r, view.pr)
  const button = (a: Action, glyph: string, label: string) => {
    const props: Record<string, unknown> = { key: `act-${a}`, label: `${view.action === a ? '▾' : glyph}${NB}${label}`, onPress: () => act.toggleAction(a) }
    if (a === lead && view.action !== a) props.variant = 'primary'
    return h(Button, props)
  }
  return (
    <Box key="bar" marginTop={1}>
      {line(
        k,
        [
          button('commit', '✓', 'Commit'),
          button('pull', '↓', 'Pull'),
          button('push', '↑', 'Push'),
          button('pr', '⇄', pr && pr.state === 'OPEN' ? `PR${NB}#${pr.number}` : `Pull${NB}request`),
        ],
        true,
      )}
    </Box>
  )
}

// ─── Tiroir de l'action choisie ─────────────────────────────────────────

const drawer = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box, Button, Input, Select, Link } = k
  const open = view.action
  if (!open) return null
  const m = view.meta
  const f = view.form
  const n = countsOf(r)
  const pr = prOfBranch(r, view.pr)
  // Les commandes /project agissent sur le dossier de la session, pas sur celui du panneau.
  const isHere = m.sessionRoot !== null && sameDir(m.sessionRoot, r.root)
  const say = (text: string, color = '') => <Box marginTop={1}>{T(k, text, color ? { color, wrap: 'wrap' } : { dim: true, wrap: 'wrap' })}</Box>
  const card = (a: Action, title: string, body: unknown[], command: string | null) => (
    <Box key={`drawer-${a}`} flexDirection="column" borderStyle="round" borderColor={ACTION_COLOR[a]} paddingX={1} marginTop={1}>
      <Box flexDirection="row" justifyContent="space-between" alignItems="center">
        {T(k, title, { color: ACTION_COLOR[a], bold: true })}
        {/* Pas de role="dismiss" : sur le desktop, il deviendrait la fermeture native du panneau. */}
        <Button key="drawer-close" plain={true} dimColor={true} label="✕" onPress={() => act.closeAction()} />
      </Box>
      {body.filter(isShown)}
      {command && !isHere && say(`Les commandes /project agissent sur le dossier de la session${m.sessionRoot ? ` (${m.sessionRoot})` : ''} : ouvre une session dans ${r.root} pour les lancer d'ici.`, C.amber)}
      {command && isHere && (
        <Box flexDirection="row" alignItems="center" marginTop={1}>
          {line(k, [<Button key="launch" variant="primary" label={`▶${NB}Lancer${NB}·${NB}${command}`} onPress={() => act.launch(a)} />, T(k, 'part dès que Claude est libre', { dim: true })])}
        </Box>
      )}
    </Box>
  )

  if (open === 'commit') {
    if (!r.files.length) return card('commit', '✓ Commit', [say("Rien à commiter : l'arbre de travail est propre.")], null)
    if (n.conflicts) return card('commit', '✓ Commit', [say('Résous d’abord les fichiers en conflit.', C.red)], null)
    return card(
      'commit',
      '✓ Commit',
      [
        say('Claude lit le diff, rédige le message et commite (fichiers indexés par chemin).'),
        Input ? (
          <Box marginTop={1}>
            <Input
              key="hint"
              label="Indice"
              placeholder="facultatif : l'intention du changement"
              value={f.hint}
              submitLabel="lancer"
              onInput={(v: string) => act.setForm({ hint: v })}
              onSubmit={async (v: string) => {
                await act.setForm({ hint: v })
                if (isHere) await act.launch('commit')
              }}
            />
          </Box>
        ) : (
          unavailable(k, "Indice indisponible ici : la commande part sans indice.")
        ),
      ],
      slash(commandFor('commit', r, f)),
    )
  }
  // HEAD détachée (aussi pendant un rebase) : ni pull, ni push, ni PR n'ont de branche.
  if (!r.branch) {
    const title = open === 'pull' ? '↓ Pull' : open === 'push' ? '↑ Push' : '⇄ Pull request'
    return card(open, title, [say('HEAD détachée : bascule sur une branche (onglet Branches) avant pull, push ou PR.', C.amber)], null)
  }
  if (open === 'pull') {
    const canBase = Boolean(r.defaultBranch && r.branch && r.branch !== r.defaultBranch)
    const fromBase = f.pullFrom === 'base' && canBase
    const options = [
      { value: 'upstream', label: r.upstream ? `${r.upstream} (sa branche distante)` : 'sa branche distante' },
      ...(canBase ? [{ value: 'base', label: `${r.defaultBranch} (branche par défaut)` }] : []),
    ]
    return card(
      'pull',
      '↓ Pull',
      [
        canBase &&
          (Select ? (
            <Box marginTop={1}>
              <Select key="pull-from" label="Depuis" options={options} value={fromBase ? 'base' : 'upstream'} onSelect={(v: string) => act.setForm({ pullFrom: v === 'base' ? 'base' : 'upstream' })} />
            </Box>
          ) : (
            unavailable(k, 'Choix de la source indisponible ici : le pull suit la branche distante.')
          )),
        fromBase
          ? say(`Intègre origin/${r.defaultBranch} : merge si la branche est publiée, rebase sinon.`)
          : r.upstream
            ? say(`pull --rebase --autostash depuis ${r.upstream}.`)
            : say("Branche pas encore publiée : rien à récupérer de son côté.", C.amber),
      ],
      fromBase || r.upstream ? slash(commandFor('pull', r, f)) : null,
    )
  }
  if (open === 'push') {
    const nothing = !r.files.length && !r.ahead && Boolean(r.upstream)
    return card(
      'push',
      '↑ Push',
      [
        say('Commit du reste, contrôles du projet, pull --rebase puis push, jamais en force.'),
        !r.hasRemote && say('Pas de dépôt distant : rien où pousser.', C.amber),
        r.hasRemote && r.branch && r.branch === r.defaultBranch && say(`Tu es sur ${r.branch} : Claude demandera s'il faut y pousser ou créer une branche.`, C.amber),
        r.hasRemote && nothing && say(`✓ Rien à pousser : tout est déjà sur ${r.upstream}.`, C.green),
        // Le numéro de version et le CHANGELOG se montent avant de pousser, pas après.
        r.hasRemote && !nothing && say(`Avant de pousser : ${VERSION_COMMAND} monte le numéro de version et le CHANGELOG d'après les commits.`, C.amber),
        r.hasRemote && !nothing && isHere && (
          <Box flexDirection="row" alignItems="center" marginTop={1}>
            {line(k, [<Button key="launch-version" label={`▶${NB}D'abord${NB}·${NB}${VERSION_COMMAND}`} onPress={() => act.launchVersion()} />])}
          </Box>
        ),
      ],
      r.hasRemote && !nothing ? slash(commandFor('push', r, f)) : null,
    )
  }
  // Pull request.
  if (!r.webUrl) return card('pr', '⇄ Pull request', [say("Pas de distant GitHub : pas de pull request possible.", C.amber)], null)
  if (pr && pr.state === 'OPEN') {
    return card(
      'pr',
      `⇄ Pull request #${pr.number}`,
      [
        say(pr.title),
        <Box marginTop={1}>
          {line(k, [T(k, `${prLabel(pr)} vers ${pr.base}`, { color: prColor(pr) }), Link && pr.url && <Link href={pr.url} label="Ouvrir sur GitHub ↗" />])}
        </Box>,
      ],
      null,
    )
  }
  if (r.branch === r.defaultBranch) {
    return card('pr', '⇄ Pull request', [say("Branche par défaut : crée d'abord une branche de travail (onglet Branches).", C.amber)], null)
  }
  const bases = unique([r.defaultBranch, ...r.branches.map((b) => b.name)].filter((b): b is string => Boolean(b) && b !== r.branch)).slice(0, 30)
  const base = f.prBase && bases.includes(f.prBase) ? f.prBase : (bases[0] ?? '')
  return card(
    'pr',
    '⇄ Pull request',
    [
      say('Titre et description tirés des commits ; la branche est poussée si besoin.'),
      pr && say(`La dernière PR de cette branche (#${pr.number}) est ${prLabel(pr).toLowerCase()} : une nouvelle sera créée.`),
      Select ? (
        bases.length > 0 && (
          <Box marginTop={1}>
            {line(
              k,
              [
                <Select key="pr-base" label="Vers" options={bases.map((b) => ({ value: b, label: b === r.defaultBranch ? `${b} (défaut)` : b }))} value={base} onSelect={(v: string) => act.setForm({ prBase: v })} />,
                <Select
                  key="pr-draft"
                  label="État"
                  options={[
                    { value: 'ready', label: 'Prête à relire' },
                    { value: 'draft', label: 'Brouillon' },
                  ]}
                  value={f.prDraft ? 'draft' : 'ready'}
                  onSelect={(v: string) => act.setForm({ prDraft: v === 'draft' })}
                />,
                <Select
                  key="pr-auto"
                  label="Fusion"
                  options={[
                    { value: 'manual', label: 'Manuelle' },
                    { value: 'auto', label: 'Auto (squash)' },
                  ]}
                  value={f.prAuto ? 'auto' : 'manual'}
                  onSelect={(v: string) => act.setForm({ prAuto: v === 'auto' })}
                />,
              ],
              true,
            )}
          </Box>
        )
      ) : (
        unavailable(k, 'Base, brouillon et fusion auto indisponibles ici : PR prête à relire vers la branche par défaut.')
      ),
    ],
    slash(commandFor('pr', r, f)),
  )
}

// ─── Onglets ──────────────────────────────────────────────────────────────

const tabsRow = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box, Button } = k
  const tabs: [Tab, string][] = [
    ['changes', `Modifications${NB}·${NB}${r.files.length}`],
    ['branches', `Branches${NB}·${NB}${r.branches.length + r.remotes.length}`],
    ['history', `Historique${NB}·${NB}${r.commits.length}`],
  ]
  return (
    <Box key="tabs" flexDirection="row" flexWrap="wrap" marginTop={1}>
      {tabs.map(([tab, label]) => (
        <Box marginRight={2}>
          <Button key={`tab-${tab}`} plain={true} dimColor={tab !== view.tab} label={tab === view.tab ? `▸${NB}${label}` : label} onPress={() => act.setTab(tab)} />
        </Box>
      ))}
    </Box>
  )
}

// ─── Modifications ────────────────────────────────────────────────────────

const GROUPS: { id: string; glyph: string; label: string; color: string; test: (f: GitFile) => boolean }[] = [
  { id: 'conflict', glyph: '✖', label: 'En conflit', color: C.red, test: (f) => f.kind === 'conflict' },
  { id: 'staged', glyph: '◆', label: 'Indexés', color: C.green, test: (f) => f.kind === 'changed' && f.work === '.' },
  { id: 'changed', glyph: '●', label: 'Modifiés', color: C.amber, test: (f) => f.kind === 'changed' && f.work !== '.' },
  { id: 'untracked', glyph: '+', label: 'Nouveaux', color: C.teal, test: (f) => f.kind === 'untracked' },
]

const changesTab = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box } = k
  if (!r.files.length) {
    return (
      <Box key="clean" flexDirection="column" borderStyle="round" borderDimColor={true} paddingX={1} marginTop={1}>
        {T(k, `✓${NB}Arbre de travail propre`, { color: C.green, bold: true })}
        {T(k, 'Rien à commiter. Les fichiers modifiés apparaîtront ici.', { dim: true, wrap: 'wrap' })}
      </Box>
    )
  }
  const n = countsOf(r)
  const sorted = GROUPS.flatMap((g) => r.files.filter(g.test).sort((a, b) => a.path.localeCompare(b.path)))
  const limit = view.expanded.files ? MAX_FILES : FILES_CAP
  const shown = new Set(sorted.slice(0, limit))
  const total = n.added + n.removed
  const cells = Math.min(24, Math.max(8, k.width - 50))
  const parts: BarPart[] = [
    { value: n.added, color: C.green },
    { value: n.removed, color: C.red },
  ]
  const bar = total > 0 ? (k.isRich ? svgOf(k, barSvg(parts, total, px(cells)), `${n.added} lignes ajoutées, ${n.removed} retirées`) : blocks(k, parts, total, cells)) : null
  // L'onglet actif dit déjà le nombre de fichiers : la carte n'ouvre que sur le total des
  // lignes et sa barre, quand il y en a.
  const head =
    total > 0 ? (
      <Box key="diff-total" flexDirection="row" justifyContent="space-between" alignItems="center">
        <Box flexShrink={1}>{line(k, [n.added > 0 && T(k, `+${n.added}`, { color: C.green }), n.removed > 0 && T(k, `−${n.removed}`, { color: C.red }), T(k, 'lignes', { dim: true })])}</Box>
        {bar && k.width >= 56 && (
          <Box flexShrink={0} marginLeft={1}>
            {bar}
          </Box>
        )}
      </Box>
    ) : null
  let isFirst = head === null
  return (
    <Box key="files" flexDirection="column" borderStyle="round" borderDimColor={true} paddingX={1} marginTop={1}>
      {head}
      {GROUPS.map((g) => {
        const files = sorted.filter((f) => g.test(f))
        const visible = files.filter((f) => shown.has(f))
        if (visible.length === 0) return null
        const top = isFirst ? 0 : 1
        isFirst = false
        return (
          <Box key={`g-${g.id}`} flexDirection="column" marginTop={top}>
            {line(k, [T(k, `${g.glyph}${NB}${g.label}`, { color: g.color, bold: true }), T(k, String(files.length), { dim: true })])}
            {visible.map((f) => fileRow(k, f))}
          </Box>
        )
      })}
      {sorted.length > FILES_CAP && showAllToggle(k, 'files-all', view.expanded.files, sorted.length, () => act.toggleExpanded('files'))}
      {view.expanded.files && sorted.length > MAX_FILES && T(k, `+${sorted.length - MAX_FILES}`, { dim: true })}
    </Box>
  )
}

const fileRow = (k: Kit, file: GitFile): unknown => {
  const { Box } = k
  const g = glyphOf(file)
  // Un dossier non suivi finit par « / » : son nom est le dernier segment, barre comprise.
  const cut = file.path.replace(/\/$/, '').lastIndexOf('/')
  const partial = file.kind === 'changed' && file.index !== '.' && file.work !== '.'
  return (
    <Box key={`f-${file.path}`} flexDirection="row">
      <Box width={2} flexShrink={0}>
        {T(k, g.letter, { color: g.color, bold: true })}
      </Box>
      <Box flexGrow={1} flexShrink={1}>
        {TT(k, [T(k, file.path.slice(0, cut + 1), { dim: true }), file.path.slice(cut + 1), file.from ? T(k, ` ← ${file.from}`, { dim: true }) : ''], { wrap: 'truncate-start' })}
      </Box>
      <Box flexShrink={0} marginLeft={1}>
        {line(k, [
          partial && T(k, `en${NB}partie${NB}indexé`, { dim: true }),
          file.added !== null && T(k, `+${file.added}`, { color: C.green }),
          file.removed !== null && T(k, `−${file.removed}`, { color: C.red }),
        ])}
      </Box>
    </Box>
  )
}

// ─── Branches ─────────────────────────────────────────────────────────────

const branchesTab = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box, Button, Input } = k
  const f = view.form
  const pending = view.switching
  const q = f.filter.trim().toLowerCase()
  const locals = r.branches.filter((b) => !q || b.name.toLowerCase().includes(q))
  const remotes = r.remotes.filter((b) => !q || b.name.toLowerCase().includes(q))
  const showRemotes = view.showRemotes || Boolean(q)
  // Chaque liste a sa bascule « tout voir » ; un filtre montre tout.
  const shownLocals = view.expanded.branches || q ? locals : locals.slice(0, BRANCHES_CAP)
  const shownRemotes = view.expanded.remotes || q ? remotes : remotes.slice(0, BRANCHES_CAP)
  return (
    <Box key="branches" flexDirection="column" marginTop={1}>
      {pending && confirmCard(k, view, r, pending, act)}
      {Input ? (
        <Box flexDirection="column" marginTop={pending ? 1 : 0}>
          <Input
            key="new-branch"
            label="Nouvelle branche"
            placeholder="feat/nom-court"
            value={f.newBranch}
            submitLabel="créer et basculer"
            onInput={(v: string) => act.setForm({ newBranch: v })}
            onSubmit={(v: string) => act.createBranch(v)}
          />
          {r.branches.length + r.remotes.length > 6 && (
            <Box marginTop={1}>
              <Input key="filter" label="Filtrer" placeholder="nom de branche" value={f.filter} onInput={(v: string) => act.setForm({ filter: v })} onSubmit={(v: string) => act.setForm({ filter: v })} />
            </Box>
          )}
        </Box>
      ) : (
        unavailable(k, 'Création et filtre de branches indisponibles ici (pas de champ de saisie).', pending ? 1 : 0)
      )}
      <Box key="locals" flexDirection="column" borderStyle="round" borderDimColor={true} paddingX={1} marginTop={1}>
        {line(k, [T(k, 'Locales', { bold: true }), T(k, String(locals.length), { dim: true })])}
        {shownLocals.map((b) => branchRow(k, view, r, b, act))}
        {q && !locals.length && !remotes.length && T(k, 'Aucune branche ne correspond.', { dim: true })}
        {!q && locals.length > BRANCHES_CAP && showAllToggle(k, 'branches-all', view.expanded.branches, locals.length, () => act.toggleExpanded('branches'))}
      </Box>
      {remotes.length > 0 && (
        <Box key="remotes" flexDirection="column" marginTop={1}>
          <Button
            key="remotes-toggle"
            plain={true}
            dimColor={true}
            label={`${showRemotes ? '▾' : '▸'}${NB}Seulement${NB}sur${NB}le${NB}distant${NB}·${NB}${remotes.length}`}
            onPress={() => act.toggleRemotes()}
          />
          {showRemotes && shownRemotes.map((b) => remoteRow(k, view, b, act))}
          {showRemotes && !q && remotes.length > BRANCHES_CAP && showAllToggle(k, 'remotes-all', Boolean(view.expanded.remotes), remotes.length, () => act.toggleExpanded('remotes'))}
        </Box>
      )}
    </Box>
  )
}

const branchRow = (k: Kit, view: View, r: GitRepo, b: GitBranch, act: Actions): unknown => {
  const { Box, Button } = k
  const track: [string, string] = b.worktree
    ? ['ouverte dans un autre worktree', C.gray]
    : b.isGone
      ? [`distante${NB}supprimée`, C.red]
      : !b.upstream
        ? ['locale', C.gray]
        : b.ahead || b.behind
          ? [[b.ahead ? `↑${b.ahead}` : '', b.behind ? `↓${b.behind}` : ''].filter(Boolean).join(NB), b.behind ? C.amber : C.green]
          : [`✓${NB}à${NB}jour`, C.green]
  return (
    <Box key={`b-${b.name}`} flexDirection="row" alignItems="center">
      <Box width={2} flexShrink={0}>
        {T(k, b.isCurrent ? '●' : '○', { color: b.isCurrent ? BRAND : C.gray, bold: b.isCurrent })}
      </Box>
      <Box flexGrow={1} flexShrink={1}>
        {TT(k, [T(k, b.name, { bold: b.isCurrent }), b.name === r.defaultBranch ? T(k, `${NB}${NB}défaut`, { dim: true }) : ''], { wrap: 'truncate-end' })}
      </Box>
      <Box flexShrink={0} marginLeft={1}>
        {line(k, [
          T(k, track[0], { color: track[1], dim: track[1] === C.gray }),
          k.width >= 64 && T(k, ago(b.date, view.now), { dim: true }),
          !b.isCurrent && !b.worktree && <Button key={`sw-${b.name}`} plain={true} dimColor={true} label={`↪${NB}basculer`} onPress={() => act.askSwitch(b.name, false)} />,
        ])}
      </Box>
    </Box>
  )
}

const remoteRow = (k: Kit, view: View, b: GitRemoteBranch, act: Actions): unknown => {
  const { Box, Button } = k
  return (
    <Box key={`rb-${b.name}`} flexDirection="row" alignItems="center">
      <Box width={2} flexShrink={0}>
        {T(k, '☁', { color: C.blue })}
      </Box>
      <Box flexGrow={1} flexShrink={1}>
        {T(k, b.name, { wrap: 'truncate-end' })}
      </Box>
      <Box flexShrink={0} marginLeft={1}>
        {line(k, [k.width >= 64 && T(k, ago(b.date, view.now), { dim: true }), <Button key={`swr-${b.name}`} plain={true} dimColor={true} label={`↪${NB}basculer`} onPress={() => act.askSwitch(b.name, true)} />])}
      </Box>
    </Box>
  )
}

const confirmCard = (k: Kit, view: View, r: GitRepo, s: NonNullable<Switching>, act: Actions): unknown => {
  const { Box, Button } = k
  const target = s.isRemote ? localOf(s.name) : s.name
  const changed = countsOf(r).changed + countsOf(r).conflicts
  return (
    <Box key="confirm" flexDirection="column" borderStyle="round" borderColor={C.amber} paddingX={1}>
      {T(k, `Basculer vers ${target} ?`, { color: C.amber, bold: true })}
      {T(k, `${plural(changed, 'fichier modifié', 'fichiers modifiés')} suivr${changed > 1 ? 'ont' : 'a'} ; git refuse si l'un entre en conflit. Pour les garder ici, commite d'abord.`, { dim: true, wrap: 'wrap' })}
      <Box marginTop={1}>
        {line(k, [
          <Button key="confirm-yes" variant="primary" label={`↪${NB}Basculer${NB}quand${NB}même`} onPress={() => act.confirmSwitch(s.name, s.isRemote)} />,
          <Button key="confirm-no" label="Annuler" onPress={() => act.cancelSwitch()} />,
        ])}
      </Box>
    </Box>
  )
}

// ─── Historique ───────────────────────────────────────────────────────────

const historyTab = (k: Kit, view: View, r: GitRepo, act: Actions): unknown => {
  const { Box } = k
  if (!r.commits.length) {
    return (
      <Box key="no-commits" flexDirection="column" borderStyle="round" borderDimColor={true} paddingX={1} marginTop={1}>
        {T(k, "Aucun commit pour l'instant.", { bold: true })}
        {T(k, 'Les commits de la branche apparaîtront ici.', { dim: true })}
      </Box>
    )
  }
  const unpushed = r.hasRemote ? r.unpushed : 0
  const shown = view.expanded.commits ? r.commits : r.commits.slice(0, COMMITS_CAP)
  return (
    <Box key="history" flexDirection="column" borderStyle="round" borderDimColor={true} paddingX={1} marginTop={1}>
      {line(k, [
        T(k, 'Historique', { bold: true }),
        T(k, `${r.commits.length}${NB}derniers`, { dim: true }),
        unpushed > 0 && T(k, `↑${NB}${unpushed >= 500 ? '500+' : unpushed}${NB}pas${NB}encore${NB}poussé${unpushed > 1 ? 's' : ''}`, { color: C.green, bold: true }),
      ])}
      {shown.map((c) => commitRow(k, view, r, c))}
      {r.commits.length > COMMITS_CAP && showAllToggle(k, 'commits-all', view.expanded.commits, r.commits.length, () => act.toggleExpanded('commits'))}
    </Box>
  )
}

const commitRow = (k: Kit, view: View, r: GitRepo, c: GitCommit): unknown => {
  const { Box, Link } = k
  const isLocal = r.hasRemote && !c.isPushed
  const tags = c.refs
    .split(', ')
    .filter((x) => x.startsWith('tag: '))
    .map((x) => `◆${NB}${x.slice(5)}`)
  return (
    <Box key={`c-${c.hash}`} flexDirection="row">
      <Box width={2} flexShrink={0}>
        {T(k, isLocal ? '↑' : '○', { color: isLocal ? C.green : C.gray, bold: isLocal })}
      </Box>
      <Box flexGrow={1} flexShrink={1}>
        {T(k, c.subject, { wrap: 'truncate-end' })}
      </Box>
      <Box flexShrink={0} marginLeft={1}>
        {line(k, [
          ...tags.map((t) => T(k, t, { color: C.violet })),
          T(k, c.short, { dim: true }),
          k.width >= 90 && T(k, c.author, { dim: true }),
          k.width >= 64 && T(k, ago(c.date, view.now), { dim: true }),
          r.webUrl && Link && <Link href={`${r.webUrl}/commit/${c.hash}`} label="↗" />,
        ])}
      </Box>
    </Box>
  )
}

// ─── Bandeau ──────────────────────────────────────────────────────────────




/** Largeur du nom dans la colonne d'étiquette, la même dans les bandeaux Git, Flow et Asana. */
const LABEL_CELLS = 5
/** La colonne d'étiquette : la barre, une espace, le nom calé sur LABEL_CELLS. */
export const TAG_CELLS = 2 + LABEL_CELLS
/** La couleur de Git dans les bandeaux (mandarine, comme son logo) ; le violet reste celui de Flow. */
const TAG_COLOR = C.tangerine

/**
 * L'étiquette d'outil en tête du bandeau : une barre verticale et le nom du mod en gras, de la
 * couleur du mod. Les bandeaux empilés s'alignent sur cette colonne et se distinguent par sa
 * couleur, sans trait horizontal (un « ─ » répété n'a pas la même largeur sur le desktop que
 * sur le terminal). `label` vide : la barre et la colonne vide, pour la ligne 2 ; `null` : la
 * barre seule, sur un bandeau trop étroit.
 */
const bandTag = (k: Kit, label: string | null, color: string): unknown => (
  <k.Box flexDirection="row" flexShrink={0}>
    {T(k, '▍', { color, bold: true })}
    {label !== null && T(k, `${NB}${label.padEnd(LABEL_CELLS, NB)}`, { color, bold: true })}
  </k.Box>
)

/**
 * Le bandeau au-dessus du prompt : une ligne, deux au plus. Rien hors d'un dépôt ni quand
 * il est masqué (le hook rend alors le bandeau du dessous).
 */
export const drawBand = (k: Kit, view: View, act: Actions): unknown => {
  const r = view.repo
  if (!r || view.isBandHidden) return null
  const { Box, Button } = k
  const width = k.width
  const m = view.meta
  const n = countsOf(r)
  const pr = prOfBranch(r, view.pr)
  const watch = ciOf(r, view.ci)
  const isElsewhere = m.sessionRoot === null || !sameDir(m.sessionRoot, r.root)
  const fetched = fetchedText(m, view.now, r.hasRemote)

  const remote = r.upstream
    ? r.ahead || r.behind
      ? line(k, [r.ahead > 0 && T(k, `↑${r.ahead}`, { color: C.green, bold: true }), r.behind > 0 && T(k, `↓${r.behind}`, { color: C.amber, bold: true })])
      : T(k, `✓${NB}à${NB}jour`, { color: C.green })
    : r.branch && r.hasRemote
      ? T(k, `◌${NB}non${NB}publiée`, { color: C.amber })
      : null
  const files = line(k, [
    n.conflicts > 0 && T(k, `✖${NB}${n.conflicts}`, { color: C.red, bold: true }),
    n.changed > 0 && T(k, `●${NB}${n.changed}`, { color: C.amber }),
    n.fresh > 0 && T(k, `+${NB}${n.fresh}`, { color: C.teal }),
  ])
  // Un « · » sépare les fichiers (« + 1 » nouveau) du total des lignes (« +13 »).
  const diff =
    width >= 72 &&
    n.added + n.removed > 0 &&
    line(k, [r.files.length > 0 && T(k, '·', { dim: true }), n.added > 0 && T(k, `+${n.added}`, { color: C.green, dim: true }), n.removed > 0 && T(k, `−${n.removed}`, { color: C.red, dim: true })])
  const prBit =
    width >= 72 &&
    pr &&
    line(k, [
      T(k, `⇄${NB}#${pr.number}`, { color: C.violet, bold: true }),
      T(k, prLabel(pr), { color: prColor(pr) }),
      ...(watch ? [ciText(watch, true)] : checksText(pr.checks)).map(([text, c]) => T(k, text, { color: c })),
    ])
  // Sans PR, la CI suivie après un push, à la place de la PR.
  const ciBit = width >= 72 && !pr && watch && T(k, ciText(watch, true)[0], { color: ciText(watch, true)[1] })
  const fetchBit = fetched && (fetched.isError ? width >= 64 && T(k, fetched.text, { color: C.red }) : width >= 90 && T(k, fetched.text, { dim: true }))

  const run = view.running
  const second =
    width < 56
      ? null
      : r.operation
        ? T(k, `${OPERATION[r.operation] ?? r.operation} en cours${n.conflicts ? `${SEP}${plural(n.conflicts, 'conflit')}` : ''}`, { color: C.red, bold: true, wrap: 'truncate-end' })
        : run
          ? line(k, [
              // Rien ne tourne tant que la commande attend son tour : « ▶ », pas de spinner.
              run.isStarted ? spinner(k, C.tangerine, view.now, 'commande en cours') : T(k, '▶', { color: C.tangerine }),
              T(k, run.isStarted ? `${run.command} en cours` : `${run.command} en file`, { color: C.tangerine, wrap: 'truncate-end' }),
            ])
          : view.busy
            ? line(k, [spinner(k, C.tangerine, view.now, 'git au travail'), T(k, view.busy, { color: C.tangerine, wrap: 'truncate-end' })])
            : null

  return (
    <Box key="git-band" flexDirection="column" width={width}>
      <Box flexDirection="row" alignItems="center" justifyContent="space-between">
        <Box flexShrink={1}>
          {line(k, [
            bandTag(k, 'Git', TAG_COLOR),
            T(k, '⎇', { color: r.operation || n.conflicts ? C.red : BRAND, bold: true }),
            <Box flexShrink={1}>{T(k, branchLabel(r), { bold: true, wrap: 'truncate-end' })}</Box>,
            width >= 90 && isElsewhere && T(k, r.name, { dim: true }),
            remote,
            r.files.length > 0 && files,
            diff,
            prBit,
            ciBit,
            fetchBit,
          ])}
        </Box>
        <Box flexDirection="row" flexShrink={0} marginLeft={1}>
          <Box marginRight={1}>
            <Button key="git-band-open" plain={true} dimColor={true} label={`▸${NB}/git`} onPress={() => act.openPane()} />
          </Box>
          {/* Pas de role="dismiss" : plusieurs bandeaux empilés auraient chacun leur fermeture native au même endroit. */}
          <Button key="git-band-hide" plain={true} dimColor={true} label="x" onPress={() => act.hideBand()} />
        </Box>
      </Box>
      {second && (
        <Box flexDirection="row">
          {bandTag(k, '', TAG_COLOR)}
          <Box flexShrink={1} marginLeft={1}>
            {second}
          </Box>
        </Box>
      )}
    </Box>
  )
}

files.hooks/svg.ts:
// Dessins SVG des surfaces distantes (desktop, VS Code, mobile). Copie des helpers de
// flow-board (hooks/svg.ts : feuille de route, anneau, barre segmentée, points, indicateurs
// vivants), plus la jauge ↑/↓ propre à git-board en fin de fichier.
//
// - Les dessins sont des images (jamais `isInteractive`, qui dessine dans un cadre à fond
//   blanc rechargé à chaque redessin) : les animations SMIL y sont probablement figées.
// - Rien qui change chaque seconde dans un SVG (les âges restent en `Text`), pour qu'un SVG
//   identique ne soit pas rechargé à chaque redessin.
// - Couleurs mi-tons et gris neutre : lisibles sur fond clair comme sombre.

const FONT = `font-family="'Segoe UI', system-ui, -apple-system, sans-serif"`
const MUTED = '#8B8B93'
const WHITE = '#FFFFFF'

export const esc = (text: string): string =>
  text.replace(/[<>&"']/g, c => ({ '<': '&lt;', '>': '&gt;', '&': '&amp;', '"': '&quot;', "'": '&apos;' })[c] ?? c)

const cut = (text: string, max: number): string =>
  max <= 1 ? '' : text.length <= max ? text : `${text.slice(0, Math.max(1, max - 1))}…`

const svg = (width: number, height: number, body: string): string =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${body}</svg>`

/** Coupe un libellé en deux lignes au plus, aux espaces ; la seconde se termine par « … » s'il en reste. */
const wrap2 = (text: string, max: number): string[] => {
  if (text.length <= max) return [text]
  const words = text.split(/\s+/)
  let first = ''
  let i = 0
  while (i < words.length) {
    const next = first ? `${first} ${words[i]}` : words[i]!
    if (next.length > max && first) break
    first = next
    i += 1
  }
  const rest = words.slice(i).join(' ')
  return rest ? [cut(first, max), cut(rest, max)] : [cut(first, max)]
}

/** Largeur moyenne d'un caractère à 11,5 px (Segoe UI, system-ui). */
const CHAR_PX = 6.2

const r1 = (n: number): number => Math.round(n * 10) / 10

export type NodeState = 'done' | 'active' | 'next' | 'pending' | 'skipped'

export type RoadNode = {
  label: string
  sub?: string
  color: string
  state: NodeState
  isOptional?: boolean
  detours?: { label: string; color: string; isActive: boolean }[]
}

export type Drawn = { source: string; width: number; height: number }

const check = (x: number, y: number, size: number, color: string): string =>
  `<path d="M${r1(x - size * 0.45)} ${r1(y + size * 0.02)} l${r1(size * 0.32)} ${r1(size * 0.32)} l${r1(size * 0.6)} ${r1(-size * 0.62)}" fill="none" stroke="${color}" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/>`

/**
 * La feuille de route : une station par phase (ou par étape pour un parcours d'une
 * phase), reliées par une ligne. Station faite pleine et cochée, station en cours
 * pulsante, segment en cours animé vers la suite, suites facultatives en pointillé,
 * détours en bulles au-dessus de leur station.
 */
export const roadmapSvg = (nodes: readonly RoadNode[], width: number): Drawn => {
  const n = nodes.length
  const w = Math.max(200, Math.round(width))
  const hasDetours = nodes.some(x => (x.detours?.length ?? 0) > 0)
  const top = hasDetours ? 34 : 8
  const cy = top + 14
  const pad = n > 1 ? Math.max(34, Math.min(64, w / (n * 2))) : w / 2
  const xs = nodes.map((_, i) => (n > 1 ? pad + (i * (w - 2 * pad)) / (n - 1) : w / 2))
  const slot = n > 1 ? (w - 2 * pad) / (n - 1) : w
  const charsAt = (i: number): number => {
    const isEdge = n > 1 && (i === 0 || i === n - 1)
    const room = n > 1 ? (isEdge ? Math.min(slot, pad + slot / 2) : slot) : Math.min(w, 260)
    return Math.max(3, Math.floor((room - 6) / CHAR_PX))
  }
  const labels = nodes.map((node, i) => wrap2(node.label, charsAt(i)))
  const isTall = labels.some(l => l.length > 1)
  const subY = cy + (isTall ? 58 : 45)
  const height = cy + (isTall ? 64 : 50)
  const defs: string[] = []
  const lines: string[] = []
  const marks: string[] = []
  const texts: string[] = []
  const bubbles: string[] = []

  for (let i = 0; i < n - 1; i++) {
    const a = nodes[i]!
    const b = nodes[i + 1]!
    const x1 = r1(xs[i]! + 15)
    const x2 = r1(xs[i + 1]! - 15)
    if (x2 <= x1) continue
    const isDone = (a.state === 'done' || a.state === 'skipped') && (b.state === 'done' || b.state === 'active' || b.state === 'skipped')
    if (isDone) {
      defs.push(
        `<linearGradient id="g${i}" gradientUnits="userSpaceOnUse" x1="${x1}" y1="0" x2="${x2}" y2="0"><stop offset="0" stop-color="${a.color}"/><stop offset="1" stop-color="${b.color}"/></linearGradient>`,
      )
      lines.push(`<line x1="${x1}" y1="${cy}" x2="${x2}" y2="${cy}" stroke="url(#g${i})" stroke-width="3" stroke-linecap="round"/>`)
    } else if (a.state === 'active' || (a.state === 'done' && b.state === 'next')) {
      lines.push(
        `<line x1="${x1}" y1="${cy}" x2="${x2}" y2="${cy}" stroke="${a.color}" stroke-opacity="0.8" stroke-width="2.5" stroke-linecap="round" stroke-dasharray="6 7"><animate attributeName="stroke-dashoffset" from="13" to="0" dur="0.9s" repeatCount="indefinite"/></line>`,
      )
    } else {
      lines.push(
        `<line x1="${x1}" y1="${cy}" x2="${x2}" y2="${cy}" stroke="${MUTED}" stroke-opacity="0.5" stroke-width="2" stroke-linecap="round" stroke-dasharray="2 6"/>`,
      )
    }
  }

  nodes.forEach((node, i) => {
    const x = r1(xs[i]!)
    const c = node.color
    switch (node.state) {
      case 'done':
        marks.push(`<circle cx="${x}" cy="${cy}" r="11" fill="${c}"/>${check(x, cy, 10, WHITE)}`)
        break
      case 'active':
        marks.push(
          `<circle cx="${x}" cy="${cy}" r="12" fill="${c}" opacity="0.4"><animate attributeName="r" values="12;21" dur="1.8s" repeatCount="indefinite"/><animate attributeName="opacity" values="0.45;0" dur="1.8s" repeatCount="indefinite"/></circle>` +
            `<circle cx="${x}" cy="${cy}" r="12" fill="${c}"/><circle cx="${x}" cy="${cy}" r="4.5" fill="${WHITE}"/>`,
        )
        break
      case 'next':
        marks.push(
          `<circle cx="${x}" cy="${cy}" r="10.5" fill="${c}" fill-opacity="0.16" stroke="${c}" stroke-width="2.4"><animate attributeName="stroke-opacity" values="1;0.35;1" dur="2.2s" repeatCount="indefinite"/></circle>` +
            `<path d="M${r1(x - 3)} ${r1(cy - 4.5)} l7 4.5 l-7 4.5 z" fill="${c}"/>`,
        )
        break
      case 'skipped':
        marks.push(
          `<circle cx="${x}" cy="${cy}" r="8" fill="none" stroke="${MUTED}" stroke-opacity="0.65" stroke-width="1.6" stroke-dasharray="2 3"/>` +
            `<line x1="${x - 4}" y1="${cy + 4}" x2="${x + 4}" y2="${cy - 4}" stroke="${MUTED}" stroke-opacity="0.65" stroke-width="1.6" stroke-linecap="round"/>`,
        )
        break
      default:
        marks.push(
          `<circle cx="${x}" cy="${cy}" r="9.5" fill="${c}" fill-opacity="0.08" stroke="${c}" stroke-opacity="${node.isOptional ? 0.5 : 0.7}" stroke-width="1.8"${node.isOptional ? ' stroke-dasharray="3 3"' : ''}/>` +
            `<text x="${x}" y="${r1(cy + 3.5)}" text-anchor="middle" ${FONT} font-size="10" font-weight="700" fill="${c}" fill-opacity="0.85">${i + 1}</text>`,
        )
    }

    // Libellés : centrés, sauf aux bords où ils s'alignent sur la station pour rester entiers.
    const isEdgeLeft = n > 1 && i === 0
    const isEdgeRight = n > 1 && i === n - 1
    const chars = charsAt(i)
    const anchor = isEdgeLeft && pad < 46 ? 'start' : isEdgeRight && pad < 46 ? 'end' : 'middle'
    const tx = anchor === 'start' ? r1(x - 12) : anchor === 'end' ? r1(x + 12) : x
    const isLit = node.state === 'active' || node.state === 'done' || node.state === 'next'
    const weight = node.state === 'active' ? 700 : isLit ? 600 : 500
    const lines = labels[i]!
    texts.push(
      `<text x="${tx}" y="${cy + 30}" text-anchor="${anchor}" ${FONT} font-size="11.5" font-weight="${weight}" fill="${isLit ? c : MUTED}"${node.state === 'skipped' ? ' fill-opacity="0.7"' : ''}>` +
        lines.map((l, j) => `<tspan x="${tx}" dy="${j === 0 ? 0 : 13}">${esc(l)}</tspan>`).join('') +
        '</text>',
    )
    if (node.sub) {
      texts.push(
        `<text x="${tx}" y="${subY}" text-anchor="${anchor}" ${FONT} font-size="10" font-weight="${node.state === 'active' ? 600 : 400}" fill="${node.state === 'active' ? c : MUTED}">${esc(cut(node.sub, chars + 2))}</text>`,
      )
    }

    // Détours : la dernière bulle au-dessus de la station, avec le nombre des autres.
    const detours = node.detours ?? []
    if (detours.length > 0) {
      const last = detours[detours.length - 1]!
      const label = `↳ ${last.label}${detours.length > 1 ? ` +${detours.length - 1}` : ''}`
      const shown = cut(label, Math.max(6, Math.floor((slot - 10) / 6)))
      const bw = Math.round(shown.length * 6.1 + 16)
      const bx = Math.min(Math.max(2, x - bw / 2), w - bw - 2)
      const by = 3
      bubbles.push(
        `<line x1="${x}" y1="${by + 18}" x2="${x}" y2="${cy - 13}" stroke="${last.color}" stroke-opacity="0.55" stroke-width="1.4" stroke-dasharray="2 2"/>` +
          `<rect x="${r1(bx)}" y="${by}" width="${bw}" height="18" rx="9" fill="${last.color}" fill-opacity="0.14" stroke="${last.color}" stroke-opacity="0.75" stroke-width="1.2">${last.isActive ? '<animate attributeName="stroke-opacity" values="0.9;0.3;0.9" dur="1.6s" repeatCount="indefinite"/>' : ''}</rect>` +
          `<text x="${r1(bx + bw / 2)}" y="${by + 12.5}" text-anchor="middle" ${FONT} font-size="10" font-weight="600" fill="${last.color}">${esc(shown)}</text>`,
      )
    }
  })

  const body = `${defs.length > 0 ? `<defs>${defs.join('')}</defs>` : ''}${lines.join('')}${bubbles.join('')}${marks.join('')}${texts.join('')}`
  return { source: svg(w, height, body), width: w, height }
}

/** Anneau de progression, le pourcentage au centre. */
export const ringSvg = (ratio: number, color: string, size = 60): Drawn => {
  const r = size / 2 - 6
  const c = 2 * Math.PI * r
  const value = Math.min(1, Math.max(0, ratio))
  const len = r1(c * value)
  const mid = size / 2
  const body =
    `<circle cx="${mid}" cy="${mid}" r="${r1(r)}" fill="none" stroke="${MUTED}" stroke-opacity="0.22" stroke-width="7"/>` +
    (value > 0
      ? `<circle cx="${mid}" cy="${mid}" r="${r1(r)}" fill="none" stroke="${color}" stroke-width="7" stroke-linecap="round" stroke-dasharray="${len} ${r1(c)}" transform="rotate(-90 ${mid} ${mid})"/>`
      : '') +
    `<text x="${mid}" y="${mid + 5}" text-anchor="middle" ${FONT} font-size="14" font-weight="700" fill="${color}">${Math.round(value * 100)}%</text>`
  return { source: svg(size, size, body), width: size, height: size }
}

export type BarPart = { value: number; color: string; isLive?: boolean }

/** Barre segmentée arrondie (fait, en cours, bloqué…), la part vivante qui respire. */
export const barSvg = (parts: readonly BarPart[], total: number, width: number, height = 9): Drawn => {
  const w = Math.max(60, Math.round(width))
  const sum = Math.max(total, parts.reduce((n, p) => n + p.value, 0), 1)
  let x = 0
  const segs: string[] = []
  for (const part of parts) {
    if (part.value <= 0) continue
    const sw = (part.value / sum) * w
    segs.push(
      `<rect x="${r1(x)}" y="0" width="${r1(sw)}" height="${height}" fill="${part.color}">${part.isLive ? '<animate attributeName="opacity" values="1;0.55;1" dur="1.6s" repeatCount="indefinite"/>' : ''}</rect>`,
    )
    x += sw
  }
  const body =
    `<defs><clipPath id="bar"><rect width="${w}" height="${height}" rx="${height / 2}"/></clipPath></defs>` +
    `<g clip-path="url(#bar)"><rect width="${w}" height="${height}" fill="${MUTED}" fill-opacity="0.22"/>${segs.join('')}</g>`
  return { source: svg(w, height, body), width: w, height }
}

/** Les derniers lancements de tests : un point vert ou rouge chacun, le dernier qui pulse. */
export const dotsSvg = (runs: readonly { ok: boolean }[], width: number, green: string, red: string): Drawn => {
  const step = 12
  const max = Math.max(1, Math.floor((Math.max(80, width) - 10) / step))
  const shown = runs.slice(-max)
  const w = Math.max(20, shown.length * step + 8)
  const h = 16
  const dots = shown.map((run, i) => {
    const x = 8 + i * step
    const c = run.ok ? green : red
    const isLast = i === shown.length - 1
    return (
      (isLast
        ? `<circle cx="${x}" cy="8" r="4" fill="${c}" opacity="0.4"><animate attributeName="r" values="4;8" dur="1.8s" repeatCount="indefinite"/><animate attributeName="opacity" values="0.45;0" dur="1.8s" repeatCount="indefinite"/></circle>`
        : '') + `<circle cx="${x}" cy="8" r="${isLast ? 4.6 : 3.8}" fill="${c}"/>`
    )
  })
  return { source: svg(w, h, dots.join('')), width: w, height: h }
}

/** Un arc qui tourne : un sous-agent au travail. */
export const spinnerSvg = (color: string, size = 14): Drawn => {
  const m = size / 2
  const r = m - 2
  const body =
    `<circle cx="${m}" cy="${m}" r="${r}" fill="none" stroke="${color}" stroke-opacity="0.22" stroke-width="2"/>` +
    `<circle cx="${m}" cy="${m}" r="${r}" fill="none" stroke="${color}" stroke-width="2" stroke-linecap="round" stroke-dasharray="${r1(r * 2)} ${r1(r * 5)}"><animateTransform attributeName="transform" type="rotate" from="0 ${m} ${m}" to="360 ${m} ${m}" dur="0.9s" repeatCount="indefinite"/></circle>`
  return { source: svg(size, size, body), width: size, height: size }
}

/** Point d'état ; pulsant quand quelque chose tourne. */
export const pulseSvg = (color: string, isPulsing: boolean, size = 12): Drawn => {
  const m = size / 2
  const body =
    (isPulsing
      ? `<circle cx="${m}" cy="${m}" r="3" fill="${color}" opacity="0.5"><animate attributeName="r" values="3;${m}" dur="1.4s" repeatCount="indefinite"/><animate attributeName="opacity" values="0.55;0" dur="1.4s" repeatCount="indefinite"/></circle>`
      : '') + `<circle cx="${m}" cy="${m}" r="3.4" fill="${color}"/>`
  return { source: svg(size, size, body), width: size, height: size }
}

/** La feuille de route du bandeau : des pastilles, sans libellés. */
export const miniRoadSvg = (nodes: readonly { color: string; state: NodeState; isOptional?: boolean }[]): Drawn => {
  const gap = 17
  const h = 16
  const w = Math.max(16, (nodes.length - 1) * gap + 16)
  const cy = h / 2
  const parts: string[] = []
  nodes.forEach((node, i) => {
    if (i === nodes.length - 1) return
    const next = nodes[i + 1]!
    const x1 = 8 + i * gap + 6
    const x2 = 8 + (i + 1) * gap - 6
    const isDone = node.state === 'done' || node.state === 'skipped'
    parts.push(
      isDone && next.state !== 'pending' && next.state !== 'next'
        ? `<line x1="${x1}" y1="${cy}" x2="${x2}" y2="${cy}" stroke="${node.color}" stroke-width="2" stroke-linecap="round"/>`
        : `<line x1="${x1}" y1="${cy}" x2="${x2}" y2="${cy}" stroke="${MUTED}" stroke-opacity="0.5" stroke-width="1.6" stroke-dasharray="2 3"/>`,
    )
  })
  nodes.forEach((node, i) => {
    const x = 8 + i * gap
    const c = node.color
    if (node.state === 'done') parts.push(`<circle cx="${x}" cy="${cy}" r="4.6" fill="${c}"/>`)
    else if (node.state === 'active')
      parts.push(
        `<circle cx="${x}" cy="${cy}" r="5" fill="${c}" opacity="0.4"><animate attributeName="r" values="5;8" dur="1.6s" repeatCount="indefinite"/><animate attributeName="opacity" values="0.5;0" dur="1.6s" repeatCount="indefinite"/></circle><circle cx="${x}" cy="${cy}" r="5.2" fill="${c}"/><circle cx="${x}" cy="${cy}" r="2" fill="${WHITE}"/>`,
      )
    else if (node.state === 'next') parts.push(`<circle cx="${x}" cy="${cy}" r="4.4" fill="none" stroke="${c}" stroke-width="2"/>`)
    else if (node.state === 'skipped') parts.push(`<circle cx="${x}" cy="${cy}" r="3" fill="${MUTED}" fill-opacity="0.5"/>`)
    else
      parts.push(
        `<circle cx="${x}" cy="${cy}" r="4.2" fill="none" stroke="${c}" stroke-opacity="${node.isOptional ? 0.45 : 0.7}" stroke-width="1.5"${node.isOptional ? ' stroke-dasharray="2 2"' : ''}/>`,
      )
  })
  return { source: svg(w, h, parts.join('')), width: w, height: h }
}

// ─── Propre à git-board ─────────────────────────────────────────────────────

/**
 * Jauge de l'écart avec le distant : à gauche les commits à récupérer (↓), à droite ceux
 * à pousser (↑), de part et d'autre d'un trait central. Les chiffres sont dans le dessin :
 * ils ne changent qu'à une relecture du dépôt, jamais à chaque seconde.
 */
export const gaugeSvg = (ahead: number, behind: number, up: string, down: string, size = 64): Drawn => {
  const w = size * 2
  const h = 34
  const mid = w / 2
  const half = mid - 12
  const scale = (n: number): number => (n <= 0 ? 0 : r1(Math.max(6, Math.min(half, (Math.log2(n + 1) / Math.log2(33)) * half))))
  const left = scale(behind)
  const right = scale(ahead)
  const body =
    `<rect x="4" y="8" width="${w - 8}" height="8" rx="4" fill="${MUTED}" fill-opacity="0.18"/>` +
    (left > 0 ? `<rect x="${r1(mid - left)}" y="8" width="${left}" height="8" rx="4" fill="${down}"/>` : '') +
    (right > 0 ? `<rect x="${mid}" y="8" width="${right}" height="8" rx="4" fill="${up}"/>` : '') +
    `<line x1="${mid}" y1="4" x2="${mid}" y2="20" stroke="${MUTED}" stroke-width="1.6" stroke-linecap="round"/>` +
    `<text x="${r1(mid - 6)}" y="31" text-anchor="end" ${FONT} font-size="11" font-weight="700" fill="${behind > 0 ? down : MUTED}">↓${behind}</text>` +
    `<text x="${r1(mid + 6)}" y="31" text-anchor="start" ${FONT} font-size="11" font-weight="700" fill="${ahead > 0 ? up : MUTED}">↑${ahead}</text>`
  return { source: svg(w, h, body), width: w, height: h }
}

